Write-Host "Verificando APIs perigosas de XSS..."
$danger = Get-ChildItem app,lib -Recurse -File -Include *.ts,*.tsx | Select-String -Pattern "dangerouslySetInnerHTML|\beval\s*\(|new\s+Function\s*\("
if ($danger) {
  $danger | ForEach-Object { Write-Host "$($_.Path):$($_.LineNumber):$($_.Line.Trim())" }
  throw "Foram encontradas APIs perigosas de XSS/execucao dinamica. Nao sera feito commit ainda."
}
Write-Host "OK: nenhuma API direta perigosa encontrada"

Write-Host "Verificando diff..."
git diff --check
if ($LASTEXITCODE -ne 0) { throw "git diff --check encontrou problema." }

Write-Host "Executando typecheck..."
npm.cmd run typecheck
$typeExit = $LASTEXITCODE
if ($typeExit -ne 0) {
  git restore -- next-env.d.ts 2>$null
  throw "TYPECHECK FALHOU. Envie apenas o erro final."
}

Write-Host "Executando build..."
npm.cmd run build
$buildExit = $LASTEXITCODE
git restore -- next-env.d.ts 2>$null
if ($buildExit -ne 0) { throw "BUILD FALHOU. Envie apenas o erro final." }

Write-Host ""
Write-Host "=============================================="
Write-Host "ETAPA 13.10 APLICADA - BUILD APROVADO"
